<?php
namespace App\Http\Controllers;
use App\Models\{User,Project,ProjectAttachment};use App\Services\Operations;use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Hash};use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class OperationsController extends Controller {
 private function people($query,Request $r){if($r->filled('search')){$term='%'.mb_substr($r->search,0,100).'%';$query->where(fn($q)=>$q->where('name','like',$term)->orWhere('email','like',$term)->orWhere('company','like',$term));}if($r->filled('status'))$query->where('status',$r->status);$sort=in_array($r->query('sort'),['name','email','created_at','status'])?$r->query('sort'):'created_at';return $query->orderBy($sort,$r->query('direction')==='asc'?'asc':'desc')->paginate(20);}
 public function clients(Request $r){return $this->people(User::where('role','client')->select(['id','name','email','company','phone','status','assigned_to','created_at','last_login_at'])->withCount('projects'),$r);}
 public function client(Request $r,User $client){abort_unless($client->role==='client',404);return ['client'=>$client->only(['id','name','email','company','phone','status','assigned_to','created_at','last_login_at']),'projects'=>$client->projects()->latest()->get(),'conversations'=>DB::table('conversations')->where('client_id',$client->id)->select('id','title','status','updated_at')->get(),'notes'=>DB::table('admin_notes')->join('users','users.id','=','admin_notes.author_id')->where('resource_type','client')->where('resource_id',$client->id)->latest('admin_notes.created_at')->get(['body','users.name as author','admin_notes.created_at'])];}
 public function updateClient(Request $r,User $client){abort_unless($client->role==='client',404);$data=$r->validate(['name'=>'sometimes|required|string|max:100','company'=>'nullable|string|max:150','phone'=>'nullable|string|max:40','status'=>'sometimes|in:active,suspended','assigned_to'=>'nullable|exists:users,id']);if(!empty($data['assigned_to']))User::where('role','!=','client')->where('status','active')->findOrFail($data['assigned_to']);DB::transaction(function()use($r,$client,$data){$client->fill($data)->save();if(($data['status']??null)==='suspended')DB::table('sessions')->where('user_id',$client->id)->delete();Operations::log($r->user(),'client.updated','client',$client->id,array_intersect_key($data,array_flip(['name','status','assigned_to','company'])));});return ['ok'=>true];}
 public function clientNote(Request $r,User $client){abort_unless($client->role==='client',404);$data=$r->validate(['body'=>'required|string|max:5000']);DB::table('admin_notes')->insert(['id'=>Str::uuid()->toString(),'resource_type'=>'client','resource_id'=>$client->id,'author_id'=>$r->user()->id,'body'=>$data['body'],'created_at'=>now(),'updated_at'=>now()]);Operations::log($r->user(),'note.added','client',$client->id);return ['ok'=>true];}
 public function lookup(Request $r){return ['clients'=>$r->user()->isManager()?User::where('role','client')->where('status','active')->orderBy('name')->limit(500)->get(['id','name','email']):[],'team'=>User::where('role','!=','client')->where('status','active')->orderBy('name')->get(['id','name','role']),'projects'=>Operations::projectScope(Project::query(),$r->user())->orderByDesc('created_at')->limit(500)->get(['id','title','owner_id']),'statuses'=>Operations::STATUSES];}
 public function team(Request $r){return $this->people(User::where('role','!=','client')->select(['id','name','email','role','status','permissions','locale','created_at','last_login_at']),$r);}
 public function saveTeam(Request $r,?User $member=null){$data=$r->validate(['name'=>'required|string|max:100','email'=>['required','email','max:254',Rule::unique('users')->ignore($member?->id)],'role'=>'required|in:super_admin,admin,team_member','status'=>'required|in:active,suspended','password'=>($member?'nullable':'required').'|string|min:12|max:256','permissions'=>'nullable|array','permissions.*'=>Rule::in(['dashboard','clients','projects','messages','files','team','content','notifications','activity','settings'])]);if($member){abort_if($member->role==='client',404);abort_if($member->id===$r->user()->id&&($data['role']!=='super_admin'||$data['status']!=='active'),422,'You cannot remove your own administrative access.');}
  DB::transaction(function()use($r,$member,$data){if($member&&$member->role==='super_admin'&&($data['role']!=='super_admin'||$data['status']!=='active'))abort_unless(User::where('role','super_admin')->where('status','active')->lockForUpdate()->get(['id'])->count()>1,422,'At least one active Super Admin is required.');$password=$data['password']??null;unset($data['password']);if($password)$data['password']=Hash::make($password);$target=$member??new User();$target->fill($data)->save();DB::table('sessions')->where('user_id',$target->id)->delete();Operations::log($r->user(),$member?'team.updated':'team.created','user',$target->id,['role'=>$target->role,'status'=>$target->status]);});return ['ok'=>true];}
 private function unread(User $user){$q=DB::table('messages as m')->join('conversations as c','c.id','=','m.conversation_id')->leftJoin('conversation_participants as p',fn($j)=>$j->on('p.conversation_id','=','c.id')->where('p.user_id',$user->id))->where('m.sender_id','!=',$user->id)->whereNull('m.deleted_at')->whereRaw('m.id>COALESCE(p.last_read_message_id,0)');if(!$user->isManager())$q->where(fn($q)=>$q->whereNull('c.assigned_to')->orWhere('c.assigned_to',$user->id));return $q->count();}
 public function overview(Request $r){$u=$r->user();$days=in_array((int)$r->query('days'),[7,30,90])?(int)$r->query('days'):30;$scope=fn()=>Operations::projectScope(Project::query(),$u);$groups=$scope()->select('status')->selectRaw('COUNT(*) as total')->groupBy('status')->get();$statuses=[];foreach($groups as $g){$name=Operations::status($g->status);$statuses[$name]=($statuses[$name]??0)+(int)$g->total;}$clients=User::where('role','client');if(!$u->isManager())$clients->whereIn('id',$scope()->select('owner_id'));
  $projectSeries=$scope()->where('created_at','>=',now()->subDays($days-1)->startOfDay())->selectRaw('DATE(created_at) as day,COUNT(*) as total')->groupBy(DB::raw('DATE(created_at)'))->pluck('total','day');$registrationSeries=(clone $clients)->where('created_at','>=',now()->subDays($days-1)->startOfDay())->selectRaw('DATE(created_at) as day,COUNT(*) as total')->groupBy(DB::raw('DATE(created_at)'))->pluck('total','day');$series=[];for($i=$days-1;$i>=0;$i--){$date=now()->subDays($i)->toDateString();$series[]=['date'=>$date,'projects'=>(int)($projectSeries[$date]??0),'clients'=>(int)($registrationSeries[$date]??0)];}
  $active=array_sum(array_intersect_key($statuses,array_flip(['Approved','In Development','Testing','Proposal Sent'])));return ['stats'=>['clients'=>(clone $clients)->count(),'active'=>$active,'pending'=>array_sum(array_intersect_key($statuses,array_flip(['New Request','Under Review','Awaiting Client Information']))),'completed'=>$statuses['Completed']??0,'unread'=>$u->allows('messages')?$this->unread($u):0,'reviews'=>$statuses['Under Review']??0,'registrations'=>(clone $clients)->where('created_at','>=',now()->subDays(7))->count(),'files'=>ProjectAttachment::whereIn('project_id',$scope()->select('id'))->count()],'statuses'=>$statuses,'series'=>$series,'recent_projects'=>$scope()->with('owner:id,name')->latest()->limit(5)->get(),'activity'=>$this->activityQuery($u)->orderByDesc('activity_logs.id')->limit(8)->get(['activity_logs.id','action','target_type','target_id','activity_logs.created_at','users.name as actor'])];}
 private function activityQuery(User $user){$q=DB::table('activity_logs')->leftJoin('users','users.id','=','activity_logs.actor_id');if(!$user->isManager())$q->where(fn($q)=>$q->where('actor_id',$user->id)->orWhere(fn($q)=>$q->where('target_type','project')->whereIn('target_id',Project::where('assigned_to',$user->id)->select('id'))));return $q;}
 public function logs(Request $r){$q=$this->activityQuery($r->user());if($r->filled('search')){$s='%'.mb_substr($r->search,0,100).'%';$q->where(fn($q)=>$q->where('action','like',$s)->orWhere('users.name','like',$s)->orWhere('target_id','like',$s));}return $q->orderByDesc('activity_logs.id')->select('activity_logs.*','users.name as actor')->paginate(25);}
 private function syncNotifications(User $user){$rows=DB::table('events as e')->join('conversations as c','c.id','=','e.conversation_id')->join('messages as m','m.id','=','e.message_id')->where('e.type','message.created')->where('e.internal',0)->where('m.sender_id','!=',$user->id)->when(!$user->isManager(),fn($q)=>$q->where(fn($q)=>$q->whereNull('c.assigned_to')->orWhere('c.assigned_to',$user->id)))->orderByDesc('e.id')->limit(200)->get(['e.id','e.conversation_id','e.created_at']);foreach($rows as $row)DB::table('admin_notifications')->insertOrIgnore(['id'=>Str::uuid()->toString(),'user_id'=>$user->id,'event_key'=>'message:'.$row->id,'kind'=>'message.created','target_type'=>'conversation','target_id'=>$row->conversation_id,'created_at'=>$row->created_at]);if($user->isManager())foreach(User::where('role','client')->latest()->limit(100)->get(['id','created_at']) as $client)DB::table('admin_notifications')->insertOrIgnore(['id'=>Str::uuid()->toString(),'user_id'=>$user->id,'event_key'=>'registration:'.$client->id,'kind'=>'client.registered','target_type'=>'client','target_id'=>$client->id,'created_at'=>$client->created_at]);}
 private function notificationQuery(User $u){$q=DB::table('admin_notifications')->where('user_id',$u->id);if(!$u->isManager())$q->where(fn($q)=>$q->where(fn($q)=>$q->where('target_type','project')->whereIn('target_id',Project::where('assigned_to',$u->id)->select('id')))->orWhere(fn($q)=>$q->where('target_type','conversation')->whereIn('target_id',DB::table('conversations')->where(fn($c)=>$c->whereNull('assigned_to')->orWhere('assigned_to',$u->id))->select('id'))));return $q;}
 public function notifications(Request $r){$this->syncNotifications($r->user());$q=$this->notificationQuery($r->user());return ['unread'=>(clone $q)->whereNull('read_at')->count(),'items'=>$q->latest('created_at')->paginate(20)];}
 public function readNotifications(Request $r){$data=$r->validate(['id'=>'nullable|uuid']);$q=$this->notificationQuery($r->user());if(!empty($data['id']))$q->where('id',$data['id']);$q->update(['read_at'=>now()]);return ['ok'=>true];}
 public function settings(Request $r){return ['brand'=>Operations::setting('brand','NorthByte'),'contact_email'=>Operations::setting('contact_email',''),'attachment_mb'=>Operations::setting('attachment_mb',config('northbyte.attachment_mb')),'registration_open'=>Operations::setting('registration_open',app()->isLocal()),'zip_uploads'=>(bool)config('northbyte.zip_uploads'),'mail_configured'=>config('mail.default')==='smtp'&&(bool)config('mail.mailers.smtp.host')];}
 public function saveSettings(Request $r){$data=$r->validate(['brand'=>'required|string|max:80','contact_email'=>'nullable|email|max:254','attachment_mb'=>'required|integer|min:1|max:'.config('northbyte.max_attachment_mb'),'registration_open'=>'required|boolean']);DB::transaction(function()use($r,$data){foreach($data as $key=>$value)DB::table('admin_settings')->updateOrInsert(['key'=>$key],['value'=>json_encode($value),'created_at'=>now(),'updated_at'=>now()]);Operations::log($r->user(),'settings.updated','settings',null,$data);});\Illuminate\Support\Facades\Cache::forget('northbyte.public');return ['ok'=>true];}
}
